// pushfold.h - solved (Nash equilibrium) short-stack push/fold ranges, generated by tools/nash.c
#pragma once
#include "range.h"

// [pusher position UTG..SB][hand class]: push when folded to you with S <= entry / 2 big blinds
extern const unsigned char PUSH_HALF_BB[5][169];

// the equilibrium push range from a position at a stack depth (pos: POS_UTG..POS_SB)
static inline bool pushHand(int pos, int cls, float bb) { return bb * 2 <= PUSH_HALF_BB[pos][cls] + 0.01f; }
static inline void pushRange(int pos, float bb, Range *out) {
    for (int k = 0; k < NCLS; k++) out->in[k] = pushHand(pos, k, bb);
}
